"""Report and slide sections for the fixed-query-budget extension."""

import csv
import json


def load_query_data(results):
    root = results / "query_study"
    def read(directory, name):
        with (directory / f"{name}.csv").open(encoding="utf-8", newline="") as f:
            return list(csv.DictReader(f))
    return {"main": read(root, "metrics"), "repeat": read(root / "repeat", "metrics"),
            "thresholds": read(root, "thresholds"),
            "manifest": json.loads((root / "manifest.json").read_text())}


def item(data, k, reads=1, rho=0., noise=.25, model="product", budget=18432, repeated=False):
    return next(r for r in data["queries"]["repeat" if repeated else "main"]
                if int(r["chains"]) == k and int(r["reads"]) == reads and float(r["correlation"]) == rho
                and float(r["noise"]) == noise and r["model"] == model and int(r["budget"]) == budget)


def effect(row):
    from build import pct
    return f"{pct(row['gain_over_single'])} [{pct(row['gain_over_single_low'])}; {pct(row['gain_over_single_high'])}]"


